  S[coll] = S[coll].filter(x => x.id !== id);
  if (db) { try { await db.collection(coll).doc(id).delete(); } catch (e) { toast("Löschen fehlgeschlagen."); } }
  else persistLocal();
}

async function initStore() {
  let handle = null;
  try { handle = window.claude?.use ? await claude.use("db") : null; } catch (e) { handle = null; }
  if (handle) {
    db = handle; mode = "db";
    $("#mode").textContent = window.BOGEY_HOSTED ? "Gemeinsam gespeichert" : "Gespeichert in deinem Claude-Konto";
    let pending = new Set(COLLS);
    COLLS.forEach(c => db.collection(c).onSnapshot(snap => {
      S[c] = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      pending.delete(c);
      if (!pending.size) { state.ready = true; render(); }
    }, () => { pending.delete(c); state.ready = true; render(); toast("Daten konnten nicht geladen werden."); }));
    db.collection("coursemaps").onSnapshot(snap => {
      for (const k in MAPS) delete MAPS[k];
      snap.docs.forEach(d => { const x = d.data(); try { MAPS[d.id] = x.json ? JSON.parse(x.json) : x; } catch (e) { } });
      if (state.ready) render();
    }, () => { });
  } else {
    mode = "local"; loadLocal(); state.ready = true;
    $("#mode").textContent = "Nur in diesem Browser gespeichert";
    render(true);
  }
}

let sample = null, sampleImages = false, sampleChecked = false, sampleMaxImages = 1;
async function initSample() {
  try {
    sample = window.claude?.use ? await claude.use("sample") : null;
    if (sample) { const lim = await sample.limits().catch(() => null); sampleImages = !!lim?.images; sampleMaxImages = Math.max(1, lim?.images?.maxCount || 1); }
  } catch (e) { sample = null; }
  sampleChecked = true;
  if (state.tab === "rounds" && state.editor) renderScanBox();
}

// ---------- Zustand & Navigation ----------
const state = { tab: "rounds", ready: false, editor: null, course: null, player: null, year: new Date().getFullYear(), statsPlayer: null, scan: null, scoring: "off" };
function editing() { return (state.tab === "rounds" && state.editor) || (state.tab === "courses" && state.course) || (state.tab === "players" && state.player); }

$("#tabs").addEventListener("click", e => {
  const b = e.target.closest("button[data-tab]"); if (!b) return;
  state.tab = b.dataset.tab; state.editor = null; state.course = null; state.player = null; state.scan = null;
  render(true);
});

function render(force) {
  document.querySelectorAll("#tabs button").forEach(b => b.setAttribute("aria-selected", String(b.dataset.tab === state.tab)));
  if (!state.ready) return;
  if (editing() && !force) return;   // Eingaben nicht durch Live-Updates überschreiben
  const m = $("#main");
  if (state.tab === "rounds") m.innerHTML = state.editor ? editorHTML() : roundsHTML();
  else if (state.tab === "stats") m.innerHTML = statsHTML();
  else if (state.tab === "players") m.innerHTML = playersHTML();
  else if (state.tab === "forecast") m.innerHTML = forecastHTML();
  else if (state.tab === "ranking") m.innerHTML = rankingHTML();
  else if (state.tab === "review") m.innerHTML = reviewHTML();
  else m.innerHTML = state.course ? courseEditorHTML() : coursesHTML();
  if (state.tab === "rounds" && state.editor) { renderScanBox(); updateResults(); }
  compactHints(m);
}
// Lange Erklärtexte auf dem Handy auf zwei Zeilen kürzen, mit „mehr“ zum Aufklappen
const mobileMQ = window.matchMedia("(max-width: 640px)");
function compactHints(root) {
  if (!mobileMQ.matches) return;
  root.querySelectorAll("p.hint").forEach(p => {
    if (p.classList.contains("long") || p.textContent.length < 150 || p.closest(".cmap-block, .scanbox, #backup-status")) return;
    p.classList.add("long");
    const b = document.createElement("button"); b.type = "button"; b.className = "hint-more"; b.textContent = "Mehr anzeigen";
    b.addEventListener("click", ev => { ev.stopPropagation(); const o = p.classList.toggle("open"); b.textContent = o ? "Weniger" : "Mehr anzeigen"; });
    p.after(b);
  });
}

// ---------- Runden ----------
function roundsHTML() {
  const rounds = [...S.rounds].sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const head = `<div class="row"><h2>Runden</h2><span class="spacer"></span><button class="btn primary" data-act="new-round">+ Neue Runde</button></div>`;
  if (!rounds.length) {
    return head + `<div class="panel empty">
      <h3>Noch keine Runden</h3>
      <ol>
        <li>Unter <b>Spieler</b> alle Mitspieler mit Handicap-Index anlegen.</li>
        <li>Unter <b>Plätze</b> deinen Platz mit Par, Lochvorgaben, CR und Slope anlegen – oder ihn beim ersten Scan übernehmen.</li>
        <li><b>Neue Runde</b> öffnen, Scorekarte fotografieren, prüfen, sichern.</li>
      </ol>
      <button class="btn primary" data-act="new-round">Erste Runde erfassen</button></div>`;
  }
  return head + `<div class="list">` + rounds.map(r => {
    const c = courseById(r.courseId); const d = new Date(r.date + "T12:00:00");
    const scores = (r.entries || []).map(e => {
      if (!c) return `<span>${esc(pName(e.playerId))}</span>`;
      const res = result(e, c);
