function renderScanBox() {
  const box = $("#scanbox"); if (!box) return;
  const sc = state.scan;
  if (!sample || !sampleImages) {
    box.innerHTML = `<p class="hint">${sampleChecked ? "Das Einlesen per Foto ist in dieser Ansicht nicht verfügbar. Trage die Schläge direkt in die Karte ein." : "Foto-Erkennung wird vorbereitet …"}</p>`;
    return;
  }
  let h = `<div class="scanbox">
    <p class="hint">Fotografiere die ausgefüllte Karte möglichst flach und vollständig oder wähle ein PDF, z. B. aus einer Golf-App. Claude liest Namen, Par, Lochvorgaben und Schläge aus – du prüfst danach alles in der Karte.</p>
    <div class="row"><label class="btn primary" for="scan-camera">Foto aufnehmen</label>
    <label class="btn" for="scan-file">Bild aus Mediathek wählen</label>
    <input type="file" id="scan-camera" accept="image/*" capture="environment" hidden>
    <label class="btn" for="scan-pdf">PDF wählen</label>
    <input type="file" id="scan-file" accept="image/*" hidden>
    <input type="file" id="scan-pdf" accept="application/pdf,.pdf" hidden></div>`;
  if (sc?.preview) h += `<img src="${sc.preview}" alt="Gescannte Scorekarte">`;
  if (sc?.status === "busy") h += `<p class="status"><span class="spin"></span>${sc.step === "pdf" ? "PDF wird geöffnet …" : "Karte wird gelesen … das dauert meist 20–60 Sekunden."}</p>`;
  if (sc?.status === "error") h += `<p class="status err">${esc(sc.msg)}</p>`;
  if (sc?.status === "done") h += mappingHTML(sc.result);
  box.innerHTML = h + `</div>`;
}

function guessPlayer(name, used) {
  const n = (name || "").toLowerCase().trim(); if (!n) return "";
  const first = n.split(/\s+/)[0];
  const hit = S.players.find(p => !used.has(p.id) && (p.name.toLowerCase() === n || p.name.toLowerCase().split(/\s+/)[0] === first || (first.length >= 3 && p.name.toLowerCase().startsWith(first.slice(0, 3)))));
  return hit ? hit.id : "";
}

function mappingHTML(r) {
  const d = state.editor, used = new Set();
