  const dl = window.claude?.use ? await claude.use("downloads").catch(() => null) : null;
  if (!dl) { if (st) st.textContent = "Speichern geht in dieser Ansicht nicht – drücke lange auf das Bild und wähle „Bild sichern“."; return; }
  try { await dl.save({ filename: cardName(d), data: cardBlob }); if (st) st.textContent = "Bild gespeichert."; }
  catch (e) { if (st) st.textContent = e?.code === "declined" ? "Speichern abgebrochen." : "Das Bild konnte nicht gespeichert werden."; }
}

// ---------- Daten-Backup ----------
function backupHTML() {
  const n = S.rounds.length;
  return `<section class="panel" id="backup"><h3>Daten-Backup</h3>
    <p class="hint">Sichert alle Spieler, Plätze, Runden und Platzkarten in einer Datei (JSON). Beim Einspielen werden Einträge mit gleicher ID überschrieben und neue ergänzt – gelöscht wird nichts. Spieler- und Luftbilder sind mit in der Datei.</p>
    <div class="row"><button class="btn primary" data-act="backup-export">Backup herunterladen</button><label class="btn" for="backup-file">Backup einspielen …</label><input type="file" id="backup-file" accept="application/json,.json" hidden></div>
    <p class="hint">${S.players.length} Spieler · ${S.courses.length} Plätze · ${n} Runde${n === 1 ? "" : "n"} · ${Object.keys(MAPS).length} Platzkarten</p>
    <div id="backup-status"></div></section>`;
}
// Bilder (Spieler, Luftbilder) als data:-URLs mitsichern, damit ein Umzug auf einen anderen Server sie mitnimmt
async function blobDataUrl(id) {
  try { const b = await (await fetch(`/_blob/${id}`)).blob(); if (!b.size || !/^image\//.test(b.type)) return null;
    return await new Promise((ok, no) => { const fr = new FileReader(); fr.onload = () => ok(fr.result); fr.onerror = no; fr.readAsDataURL(b); }); }
  catch (e) { return null; }
}
async function backupData() {
  const strip = o => { const { uploading, ...r } = o; return r; };
  const maps = Object.fromEntries(Object.entries(MAPS).map(([k, m]) => [k, { json: JSON.stringify(m) }]));
  const ids = [...new Set([...S.players, ...S.courses].map(x => x.photo).filter(Boolean))];
  const images = {};
  for (const id of ids) { const u = await blobDataUrl(id); if (u) images[id] = u; }
  return { app: "Bogey Club", kind: "backup", version: 2, exportedAt: new Date().toISOString(),
    players: S.players.map(strip), courses: S.courses.map(strip), rounds: S.rounds.map(strip), coursemaps: maps, images };
}
async function exportBackup() {
  const st = $("#backup-status"), say = t => st && (st.innerHTML = `<p class="hint">${esc(t)}</p>`);
  say("Backup wird erstellt …");
  const blob = new Blob([JSON.stringify(await backupData(), null, 1)], { type: "application/json" });
  const dl = window.claude?.use ? await claude.use("downloads").catch(() => null) : null;
  if (!dl) { say("Speichern ist in dieser Ansicht nicht möglich. Öffne die Seite in der Claude-App oder auf claude.ai."); return; }
  try { await dl.save({ filename: `Bogey-Club-Backup-${today()}.json`, data: blob }); say("Backup gespeichert."); }
