const blocks = css.split(/(?=\/\* )/).filter(b => /^\/\* latin(-ext)? \*\//.test(b));
let out = "/* Barlow Condensed und Public Sans, SIL Open Font License 1.1 (Google Fonts) */\n";
let i = 0;
