NSGraphicsContext.current = NSGraphicsContext(cgContext: ctx, flipped: false)
let font = NSFont.systemFont(ofSize: 40, weight: .medium)
func text(_ s: String, _ x: Int, _ y: Int) { NSAttributedString(string: s, attributes: [.font: font, .foregroundColor: NSColor.black]).draw(at: NSPoint(x: x, y: y)) }
let rows: [(String, [String])] = [("Loch", (1...9).map(String.init) + ["Out"]), ("Par", ["4","5","3","4","4","3","5","4","4","36"]), ("Hcp", ["7","1","15","9","3","17","5","11","13",""]), ("Julia", ["5","6","4","","5","4","6","5","5","45"]), ("Peter", ["4","5","3","5","4","3","6","4","5","39"])]
