NSGraphicsContext.current = nil
let image = ctx.makeImage()!
func run(_ level: VNRequestTextRecognitionLevel, roi: CGRect? = nil, label: String) {
  let req = VNRecognizeTextRequest(); req.recognitionLevel = level; req.usesLanguageCorrection = false
  if let roi { req.regionOfInterest = roi }
  try! VNImageRequestHandler(cgImage: image).perform([req])
  let s = (req.results ?? []).map { "\($0.topCandidates(1).first!.string)@\(String(format: "%.2f,%.2f", $0.boundingBox.midX, $0.boundingBox.midY))" }
  print(label, s.joined(separator: " "))
}
let t0 = Date()
run(.fast, label: "FAST")
print(Date().timeIntervalSince(t0))
// hole "3" at x = 330+2*115=560 → 0.35+; y=480 → row center ~ 0.716
for (i, x) in [0.358, 0.43, 0.705].enumerated() {
