    let store = try! Store()
    ctrl = WebController(store: store)
    window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 1100, height: 900), styleMask: [.titled], backing: .buffered, defer: false)
    window.contentViewController = ctrl
    window.setFrameOrigin(NSPoint(x: -3000, y: -3000)); window.orderFrontRegardless()
    Task { await self.run() }
  }
  func js(_ code: String) async -> Any? {
    let wv = ctrl.view as! WKWebView
    do { return try await wv.callAsyncJavaScript(code, contentWorld: .page) } catch { return "JSERR \(error)" }
  }
  func snap(_ name: String) async {
    let wv = ctrl.view as! WKWebView
    let img = try! await wv.takeSnapshot(configuration: nil)
    let rep = NSBitmapImageRep(data: img.tiffRepresentation!)!
    try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: "/tmp/bogeyharness/\(name).png"))
  }
  func run() async {
    try? await Task.sleep(nanoseconds: 3_000_000_000)
    let script = try! String(contentsOfFile: "/tmp/bogeyharness/test.js", encoding: .utf8)
    let r = await js(script)
    print("RESULT", r ?? "nil")
    await js("document.querySelector('#tabs button[data-tab=players]').click()"); try? await Task.sleep(nanoseconds: 800_000_000); await snap("players")
    await js("document.querySelector('#tabs button[data-tab=rounds]').click(); document.querySelector('[data-act=new-round]').click()"); try? await Task.sleep(nanoseconds: 800_000_000); await snap("newround")
    await js("document.querySelector('#tabs button[data-tab=stats]').click()"); try? await Task.sleep(nanoseconds: 800_000_000); await snap("stats")
    NSApp.terminate(nil)
  }
}
MainActor.assumeIsolated { let a = NSApplication.shared; let d = H(); a.delegate = d; withExtendedLifetime(d) { a.run() } }
