g.fillText('Golfclub Am See   14.09.2026', 60, 80);
rows.forEach(([l, vals], r) => { const y = 200 + r * 90; g.fillText(l, 60, y); vals.forEach((v, i) => g.fillText(v, 330 + i * 115, y)); });
