// Wörter wie im Swift-Test: Vision-Koordinaten
const row = (label, values, y, firstX = 0.2, step = 0.035) => {
  const t = []; if (label) t.push({ text: label, x: 0.02, y, w: 0.1, h: 0.03 });
  values.forEach((v, i) => { if (v) t.push({ text: v, x: firstX + i * step - 0.01, y, w: 0.02, h: 0.03 }); }); return t; };
const r = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => String(a + i));
let tk = [{ text: "Golfclub", x: 0.3, y: 0.92, w: 0.15, h: 0.03 }, { text: "Bruchsal", x: 0.46, y: 0.92, w: 0.14, h: 0.03 }, { text: "15.11.2026", x: 0.7, y: 0.92, w: 0.1, h: 0.03 },
  ...row("Loch", [...r(1, 9), "Out", ...r(10, 18), "In", "Total"], 0.8),
  ...row("Gelb", ["312","455","160","350","330","140","480","360","340","2927"], 0.75),
  ...row("Par", ["4","5","3","4","4","3","5","4","4","36","4","4","3","5","4","4","3","5","4","36","72"], 0.7),
  ...row("Hcp", ["7","1","15","9","3","17","5","11","13","","8","2","16","10","4","18","6","12","14","",""], 0.65),
