  ...row("Anna", ["4","5","4","4","5","3","5","5","4","39","5","4","3","6","4","5","3","5","5","40","79"], 0.55),
  ...row("Punkte", ["2","2","3","2","0","2","2","1","2"], 0.5)];
let p = O.parse([tk]);
eq(p.course, "Golfclub Bruchsal", "course"); eq(p.date, "2026-11-15", "date");
eq(p.par, [4,5,3,4,4,3,5,4,4,4,4,3,5,4,4,3,5,4], "par18"); eq(p.strokeIndex, [7,1,15,9,3,17,5,11,13,8,2,16,10,4,18,6,12,14], "si18");
eq(p.players.map(x => x.name), ["Marcel", "Anna"], "names"); eq(p.players[0].strokes, [5,6,3,5,0,4,6,5,4,5,5,4,6,5,4,3,6,5], "marcel");
tk = [...row("Loch", r(1, 9), 0.9), ...row("Par", ["4","4","3","5","4","4","3","5","4"], 0.85), ...row("Tom", ["5","5","4","6","5","5","4","6","5"], 0.8),
