// Echte Erkennung mit Tesseract auf der gezeichneten Karte, mit Nachlesen leerer Zellen
(async () => {
  const { createWorker } = require("tesseract.js");
  const W = 1600, H = 700, img = "card.png";
  const worker = await createWorker("deu");
  const read = async (rect, psm) => { await worker.setParameters({ tessedit_pageseg_mode: psm });
    const { data } = await worker.recognize(img, rect ? { rectangle: rect } : {});
    return (data.words || []).flatMap(w => String(w.text).split(/[ |]+/).filter(Boolean).map(t => ({ text: t, x: w.bbox.x0 / W, y: 1 - w.bbox.y1 / H, w: (w.bbox.x1 - w.bbox.x0) / W, h: (w.bbox.y1 - w.bbox.y0) / H }))); };
  const t0 = Date.now(); const tokens = await read(null, "11");
  const miss = O.missingCells(tokens); let fixed = 0;
  for (const cell of miss) for (const [fw, fh] of [[1.2, 2.4], [2.2, 4.0]]) {
    const w = cell.spacing * fw, h = cell.height * fh, left = Math.max(0, Math.round((cell.x - w / 2) * W)), top = Math.max(0, Math.round((1 - cell.y - h / 2) * H));
    const f = (await read({ left, top, width: Math.min(W - left, Math.round(w * W)), height: Math.min(H - top, Math.round(h * H)) }, "6"))
      .filter(t => O.parseNumber(t.text) != null && Math.abs(t.x + t.w / 2 - cell.x) < cell.spacing * 0.45);
    if (f.length) { tokens.push(f[0]); fixed++; break; }
  }
  const res = O.parse([tokens]);
  console.log("TESSERACT", Date.now() - t0, "ms, missing", miss.length, "refilled", fixed);
  eq(res.date, "2026-10-12", "t-date"); eq(res.course, "Golfclub Am See", "t-course");
