            for k in 1..<5 {
                let x = card.minX + CGFloat(k) * 94
                let p = NSBezierPath(); p.move(to: NSPoint(x: x, y: card.minY)); p.line(to: NSPoint(x: x, y: head.minY - 10)); p.lineWidth = 3; p.stroke()
