        STEEL.setFill(); NSRect(x: x0 + len - 80, y: y0, width: 36, height: w).fill()
        ROSE.setFill(); NSBezierPath(roundedRect: NSRect(x: x0 + len - 50, y: y0, width: 50, height: w), xRadius: 16, yRadius: 16).fill()
