                   ("256x256", 256), ("256x256@2x", 512), ("512x512", 512), ("512x512@2x", 1024)] {
    try! render(px).write(to: root.appendingPathComponent("icon_\(name).png"))
}
print("Icon gezeichnet: \(root.path)")

