func drawIcon(detail: Bool, fullBleed: Bool = false) {
    let tile = NSRect(x: 100, y: 100, width: 824, height: 824)
    if fullBleed {
        // Die Kachel füllt das ganze Bild; der Inhalt wird mitskaliert
        let t = NSAffineTransform(); t.scale(by: 1024 / 824); t.translateX(by: -100, yBy: -100); t.concat()
    }
    let tilePath = fullBleed ? NSBezierPath(rect: tile) : NSBezierPath(roundedRect: tile, xRadius: 186, yRadius: 186)

    // Grundplatte mit Schatten
    if fullBleed { GD.setFill(); tilePath.fill() } else { shadow(28, 12, 0.35) { GD.setFill(); tilePath.fill() } }
    NSGraphicsContext.saveGraphicsState()
    tilePath.addClip()
    NSGradient(starting: G2, ending: G1)!.draw(in: tile, angle: -90)
    // Mähstreifen wie auf dem Fairway
    if detail {
        NSColor.white.withAlphaComponent(0.045).setFill()
        for i in stride(from: -4, to: 8, by: 2) {
            let p = NSBezierPath()
            let x = CGFloat(i) * 120 + 100
            p.move(to: NSPoint(x: x, y: 100)); p.line(to: NSPoint(x: x + 120, y: 100))
            p.line(to: NSPoint(x: x + 120 + 824, y: 924)); p.line(to: NSPoint(x: x + 824, y: 924)); p.close(); p.fill()
        }
    }
    // Lichtkante oben
    NSGradient(starting: NSColor.white.withAlphaComponent(0.16), ending: NSColor.white.withAlphaComponent(0))!
        .draw(in: NSRect(x: 100, y: 700, width: 824, height: 224), angle: -90)
    NSGraphicsContext.restoreGraphicsState()
    if !fullBleed {
        NSColor.white.withAlphaComponent(0.12).setStroke()
        let rim = NSBezierPath(roundedRect: tile.insetBy(dx: 3, dy: 3), xRadius: 183, yRadius: 183); rim.lineWidth = 6; rim.stroke()

