/* Bogey Club – Theme der GitHub-Pages-Seite. Farben und Schriften wie in der App (web/index.html). */
@font-face { font-family: "Barlow Condensed"; font-weight: 600; font-display: swap; src: url(../fonts/BarlowCondensed-600-latin.woff2) format("woff2"); }
@font-face { font-family: "Barlow Condensed"; font-weight: 700; font-display: swap; src: url(../fonts/BarlowCondensed-700-latin.woff2) format("woff2"); }
@font-face { font-family: "Public Sans"; font-weight: 400; font-display: swap; src: url(../fonts/PublicSans-400-latin.woff2) format("woff2"); }
@font-face { font-family: "Public Sans"; font-weight: 600; font-display: swap; src: url(../fonts/PublicSans-600-latin.woff2) format("woff2"); }

:root {
  --bg: #eef3ef; --surface: #ffffff; --ink: #142019; --muted: #58675e; --line: #d3ddd5;
  --accent: #1c6641; --accent-ink: #ffffff; --accent-soft: #d6eadc;
  --green-1: #0c3c25; --green-2: #22764a; --cream: #f8f4e8; --gold: #deae2e;
  --radius: 14px; --shadow: 0 1px 2px rgba(20, 32, 25, .06), 0 8px 24px rgba(20, 32, 25, .08);
  --head: "Barlow Condensed", "Arial Narrow", sans-serif;
  --body: "Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1612; --surface: #17211b; --ink: #e8efe9; --muted: #9fb0a5; --line: #2a3a30;
    --accent: #5fc48c; --accent-ink: #0c1a12; --accent-soft: #1f3a2a;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 8px 24px rgba(0, 0, 0, .25);
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 80px; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 400 17px/1.6 var(--body); -webkit-font-smoothing: antialiased; }
img { max-width: 100%; height: auto; }
a { color: var(--accent); text-underline-offset: 3px; }
h1, h2, h3 { font-family: var(--head); font-weight: 700; line-height: 1.05; letter-spacing: .01em; margin: 0 0 .4em; }
h1 { font-size: clamp(48px, 8vw, 88px); text-transform: uppercase; }
h2 { font-size: clamp(32px, 4.5vw, 44px); text-transform: uppercase; }
h3 { font-size: 24px; }
.wrap { max-width: 1100px; margin: 0 auto; padding: 0 24px; }
.skip { position: absolute; left: -999px; }
.skip:focus { left: 16px; top: 16px; z-index: 10; background: var(--surface); padding: 8px 12px; border-radius: 8px; }

