.prose li { margin: .3em 0; }

/* Fuß */
.site-footer { border-top: 1px solid var(--line); padding: 32px 0 40px; }
.foot { display: flex; flex-wrap: wrap; gap: 12px 32px; align-items: center; justify-content: space-between; }
.foot-brand { display: flex; align-items: center; gap: 10px; }
.foot-brand img { border-radius: 7px; }
.fine { margin: 0; color: var(--muted); font-size: 14px; }

@media (max-width: 760px) {
  .hero-grid { grid-template-columns: 1fr; padding-top: 48px; }
  .hero-art { order: -1; }
  .hero-logo { width: 180px; }
  .nav { gap: 14px; }
  .nav .nav-gh { display: none; }
  .shot { margin-top: 24px; }
