input.content:
/* Bogey Club – Theme der GitHub-Pages-Seite. Farben und Schriften wie in der App (web/index.html). */
@font-face { font-family: "Barlow Condensed"; font-weight: 600; font-display: swap; src: url(../fonts/BarlowCondensed-600-latin.woff2) format("woff2"); }
@font-face { font-family: "Barlow Condensed"; font-weight: 700; font-display: swap; src: url(../fonts/BarlowCondensed-700-latin.woff2) format("woff2"); }
@font-face { font-family: "Public Sans"; font-weight: 400; font-display: swap; src: url(../fonts/PublicSans-400-latin.woff2) format("woff2"); }
@font-face { font-family: "Public Sans"; font-weight: 600; font-display: swap; src: url(../fonts/PublicSans-600-latin.woff2) format("woff2"); }

:root {
  --bg: #eef3ef; --surface: #ffffff; --ink: #142019; --muted: #58675e; --line: #d3ddd5;
  --accent: #1c6641; --accent-ink: #ffffff; --accent-soft: #d6eadc;
  --green-1: #0c3c25; --green-2: #22764a; --cream: #f8f4e8; --gold: #deae2e;
  --radius: 14px; --shadow: 0 1px 2px rgba(20, 32, 25, .06), 0 8px 24px rgba(20, 32, 25, .08);
  --head: "Barlow Condensed", "Arial Narrow", sans-serif;
  --body: "Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1612; --surface: #17211b; --ink: #e8efe9; --muted: #9fb0a5; --line: #2a3a30;
    --accent: #5fc48c; --accent-ink: #0c1a12; --accent-soft: #1f3a2a;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 8px 24px rgba(0, 0, 0, .25);
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 80px; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 400 17px/1.6 var(--body); -webkit-font-smoothing: antialiased; }
img { max-width: 100%; height: auto; }
a { color: var(--accent); text-underline-offset: 3px; }
h1, h2, h3 { font-family: var(--head); font-weight: 700; line-height: 1.05; letter-spacing: .01em; margin: 0 0 .4em; }
h1 { font-size: clamp(48px, 8vw, 88px); text-transform: uppercase; }
h2 { font-size: clamp(32px, 4.5vw, 44px); text-transform: uppercase; }
h3 { font-size: 24px; }
.wrap { max-width: 1100px; margin: 0 auto; padding: 0 24px; }
.skip { position: absolute; left: -999px; }
.skip:focus { left: 16px; top: 16px; z-index: 10; background: var(--surface); padding: 8px 12px; border-radius: 8px; }

/* Kopfzeile */
.site-header { position: sticky; top: 0; z-index: 5; background: color-mix(in srgb, var(--bg) 88%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); }
.bar { display: flex; align-items: center; gap: 24px; min-height: 64px; }
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); font: 700 26px/1 var(--head); text-transform: uppercase; letter-spacing: .02em; }
.brand img { border-radius: 9px; }
.nav { margin-left: auto; display: flex; gap: 22px; flex-wrap: wrap; }
.nav a { color: var(--muted); text-decoration: none; font: 600 18px/1 var(--head); text-transform: uppercase; letter-spacing: .05em; padding: 6px 0; border-bottom: 2px solid transparent; }
.nav a:hover, .nav a[aria-current] { color: var(--ink); border-color: var(--gold); }

/* Startbereich */
.hero { background: linear-gradient(160deg, var(--green-2), var(--green-1)); color: var(--cream); position: relative; overflow: hidden; }
.hero::before { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(45deg, rgba(255,255,255,.045) 0 60px, transparent 60px 120px); }
.hero-grid { position: relative; display: grid; grid-template-columns: 1.3fr 1fr; gap: 40px; align-items: center; padding-top: 72px; padding-bottom: 80px; }
.hero h1 { color: var(--cream); margin-bottom: .15em; }
.hero .kicker { color: var(--gold); }
.hero .lead { font-size: 24px; color: var(--cream); }
.hero .sub { color: rgba(248, 244, 232, .82); max-width: 34em; }
.hero-art { display: flex; justify-content: center; }
.hero-logo { width: min(340px, 80%); border-radius: 22%; box-shadow: 0 30px 60px rgba(0,0,0,.35); transform: rotate(-3deg); }
.kicker { font: 700 18px/1 var(--head); text-transform: uppercase; letter-spacing: .12em; color: var(--accent); margin: 0 0 12px; }
.lead { font-size: 20px; color: var(--muted); }

/* Knöpfe */
.actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }
.actions.center { justify-content: center; }
.btn { display: inline-flex; align-items: center; padding: 12px 22px; border-radius: 999px; font: 600 16px/1 var(--body); text-decoration: none; border: 2px solid currentColor; color: inherit; }
.btn.primary { background: var(--gold); border-color: var(--gold); color: #1a2410; }
.btn.ghost { border-color: transparent; text-decoration: underline; text-underline-offset: 4px; }
.band .btn.primary, .section .btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn:hover { filter: brightness(1.06); transform: translateY(-1px); }

/* Bildschirmfoto */
.shot { margin-top: -40px; position: relative; }
.shot figure { margin: 0; }
.shot img { display: block; border-radius: var(--radius); box-shadow: var(--shadow); border: 1px solid var(--line); }
.shot figcaption { color: var(--muted); font-size: 14px; text-align: center; margin-top: 10px; }

/* Abschnitte und Karten */
.section { padding-top: 72px; padding-bottom: 72px; }
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 18px; margin-top: 24px; }
.card, .platform { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); }
.card p, .platform p { margin: 0; color: var(--muted); }
.card-ic { display: inline-grid; place-items: center; width: 48px; height: 48px; border-radius: 12px; background: var(--accent-soft); color: var(--accent); margin-bottom: 14px; }
.ic { width: 26px; height: 26px; }
.band { background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.band .platform { background: var(--bg); box-shadow: none; display: flex; flex-direction: column; gap: 10px; }
.platforms { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 16px; margin-top: 24px; }
.platform h3 { margin: 0; }
.platform .file { font: 600 15px/1.3 var(--head); text-transform: uppercase; letter-spacing: .06em; color: var(--ink); }
.platform .link { margin-top: auto; font-weight: 600; text-decoration: none; }

/* Textseiten */
.page-body { padding-top: 56px; padding-bottom: 80px; max-width: 820px; }
.page-head { border-bottom: 3px solid var(--gold); margin-bottom: 32px; padding-bottom: 16px; }
.page-head h1 { font-size: clamp(40px, 6vw, 64px); }
.prose h2 { font-size: 34px; margin-top: 1.6em; }
.prose h3 { margin-top: 1.4em; }
.prose code { font: 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace; background: var(--accent-soft); padding: 2px 6px; border-radius: 6px; }
.prose pre { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; overflow: auto; }
.prose pre code { background: none; padding: 0; }
.prose table { border-collapse: collapse; width: 100%; margin: 1em 0; font-size: 15px; }
.prose th, .prose td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); }
.prose th { font: 700 15px/1 var(--head); text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.prose blockquote { margin: 1em 0; padding: 12px 18px; border-left: 4px solid var(--gold); background: var(--surface); border-radius: 0 10px 10px 0; color: var(--muted); }
.prose li { margin: .3em 0; }

/* Fuß */
.site-footer { border-top: 1px solid var(--line); padding: 32px 0 40px; }
.foot { display: flex; flex-wrap: wrap; gap: 12px 32px; align-items: center; justify-content: space-between; }
.foot-brand { display: flex; align-items: center; gap: 10px; }
.foot-brand img { border-radius: 7px; }
.fine { margin: 0; color: var(--muted); font-size: 14px; }

@media (max-width: 760px) {
  .hero-grid { grid-template-columns: 1fr; padding-top: 48px; }
  .hero-art { order: -1; }
  .hero-logo { width: 180px; }
  .nav { gap: 14px; }
  .nav .nav-gh { display: none; }
  .shot { margin-top: 24px; }
}

