const db = await claude.use('db');
for (let i = 0; i < 50 && !document.querySelector('#mode')?.textContent; i++) await new Promise(r => setTimeout(r, 100));
const players = [['pa', 'Anna', 16.2], ['pb', 'Ben', 24.8], ['pc', 'Clara', 11.5], ['pd', 'David', 31.0]];
for (const [id, name, hcp] of players) await db.collection('players').doc(id).set({ name, hcp, hidden: false });
const pars = [4,5,3,4,4,3,5,4,4,4,4,3,5,4,4,3,5,4], si = [7,1,15,9,3,17,5,11,13,8,2,16,10,4,18,6,12,14];
await db.collection('courses').doc('cs').set({ name: 'Golfclub Am See', cr: 71.4, slope: 131, pars, si });
await db.collection('courses').doc('cw').set({ name: 'Golfpark Waldblick', cr: 70.2, slope: 125, pars: [4,4,3,5,4,4,3,5,4,4,3,4,5,4,4,3,4,5], si: [3,9,17,1,11,5,15,7,13,4,18,10,2,12,6,16,8,14] });
let seed = 7; const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
const dates = ['2026-04-12','2026-05-03','2026-05-24','2026-06-14','2026-07-05','2026-07-26','2026-08-16','2026-09-06','2026-09-27','2026-10-18'];
for (const [k, date] of dates.entries()) {
  const c = k % 3 === 2 ? 'cw' : 'cs';
  const entries = players.map(([id, , hcp]) => ({ playerId: id, hcp, strokes: pars.map(p => Math.max(2, p + Math.round(hcp / 18 + (rnd() - 0.45) * 2.4))) }));
  await db.collection('rounds').doc('r' + k).set({ date, courseId: c, entries });
}
await new Promise(r => setTimeout(r, 500));
return S.rounds.length;
EOF
