const { app, BrowserWindow, protocol } = require("electron");
const fs = require("fs"), path = require("path");
protocol.registerSchemesAsPrivileged([{ scheme: "site", privileges: { standard: true, secure: true, supportFetchAPI: true } }]);
const ROOT = "/tmp/bogeyjekyll/preview";
const MIME = { ".html": "text/html", ".css": "text/css", ".png": "image/png", ".woff2": "font/woff2", ".xml": "text/xml" };
app.whenReady().then(async () => {
  protocol.handle("site", req => {
    let p = decodeURIComponent(new URL(req.url).pathname); if (p.endsWith("/")) p += "index.html";
    const f = path.join(ROOT, p);
    return fs.existsSync(f) ? new Response(fs.readFileSync(f), { headers: { "content-type": MIME[path.extname(f)] || "application/octet-stream" } }) : new Response("nf", { status: 404 });
  });
  for (const [name, w, url, dark] of [["home", 1280, "site://x/", false], ["home-dark", 1280, "site://x/", true], ["mobile", 390, "site://x/", false], ["anleitung", 1280, "site://x/anleitung/", false]]) {
    const win = new BrowserWindow({ width: w, height: 900, show: false });
    if (dark !== undefined) require("electron").nativeTheme.themeSource = dark ? "dark" : "light";
    await win.loadURL(url);
    await new Promise(r => setTimeout(r, 600));
    const h = await win.webContents.executeJavaScript("document.documentElement.scrollHeight");
    win.setContentSize(w, Math.min(h, 4000)); await new Promise(r => setTimeout(r, 400));
    fs.writeFileSync(`/tmp/bogeysite/${name}.png`, (await win.webContents.capturePage()).toPNG());
    win.destroy();
  }
  app.quit();
});
EOF
